$\begin{aligned}
& {[\mathrm{F}]=[\mathrm{a} \sqrt{\mathrm{x}}] \Rightarrow[\mathrm{a}]=\frac{[\mathrm{F}]}{[\sqrt{\mathrm{x}}]}} \\
& {[\mathrm{F}]=\left[\mathrm{bt}^2\right] \Rightarrow[\mathrm{b}]=\frac{[\mathrm{F}]}{\left[\mathrm{t}^2\right]}}
\end{aligned}\begin{aligned} \therefore\left[\frac{\mathrm{a}}{\mathrm{b}}\right]=\frac{[\mathrm{F}]}{[\sqrt{\mathrm{x}}]} \times \frac{\left[\mathrm{t}^2\right]}{[\mathrm{F}]} & =\frac{\left[\mathrm{t}^2\right]}{\left[\frac{1}{\frac{1}{2}}\right]}=\frac{\left[\mathrm{T}^2\right]}{\left[\frac{1}{\mathrm{~L}^2}\right]} \\ & =\left[\mathrm{M}^0 \mathrm{~L}^{-1 / 2} \mathrm{~T}^2\right]\end{aligned}$
